import { execFile } from "node:child_process";
import { cp, mkdir, readdir, symlink, writeFile } from "node:fs/promises";
import { createRequire } from "node:module";
import { dirname, join } from "node:path";
import { promisify } from "node:util";

/**
 * A real Prisma client, generated by the workspace's own `prisma` (6.x) into a project directory, on a SQLite file: the
 * engine it runs is the one `@prisma/engines` downloaded at install, and nothing here reaches the network. What is
 * tested is where `prisma-client-js` puts the class and how its runtime is loaded, and a stand-in for that would be a
 * stand-in for the answer.
 *
 * The two places a client is generated:
 *
 * - **default**: `node_modules/.prisma/client`, which `@prisma/client` re-exports — every Prisma 4 and 5 project, and a
 *   6 one with no `output`. Prisma writes it beside the `@prisma/client` it resolves, so the project gets a copy of the
 *   package's own files, and its `runtime` linked: generating into the workspace's would be generating into every test.
 * - **output**: a directory of the project's (`generated/prisma`), which requires the runtime itself and which
 *   `@prisma/client` never loads — what Prisma 6 asks for, and warns without.
 */

const run = promisify(execFile);
const require = createRequire(import.meta.url);

/** The workspace's `@prisma/client` and `prisma`, the CLI a project's `prepare` runs from its `node_modules`. */
export const PRISMA_CLIENT_DIR = dirname(require.resolve("@prisma/client/package.json"));
export const PRISMA_DIR = dirname(require.resolve("prisma/package.json"));
const PRISMA_CLI = join(PRISMA_DIR, "build", "index.js");

export type PrismaLayout = "default" | "output";

/** Where the generated client is required from: the package's name, or the project's own directory. */
export const CLIENT_REQUEST: Record<PrismaLayout, string> = {
  default: "@prisma/client",
  output: "./generated/prisma",
};

const MODELS = `
model User {
  id    Int    @id @default(autoincrement())
  email String @unique
  posts Post[]
}

model Post {
  id       Int    @id @default(autoincrement())
  title    String
  authorId Int
  author   User   @relation(fields: [authorId], references: [id])
}
`;

/** No telemetry, no update check, no install of a missing client: a CLI that would reach the network does not. */
export const PRISMA_QUIET = {
  CHECKPOINT_DISABLE: "1",
  PRISMA_HIDE_UPDATE_MESSAGE: "1",
  PRISMA_GENERATE_SKIP_AUTOINSTALL: "1",
  PRISMA_DISABLE_WARNINGS: "1",
};

/** The schema `generatePrisma` writes at `prisma/schema.prisma`, for a project that commits it first. */
export function prismaSchema(layout: PrismaLayout, database: string): string {
  const output = layout === "output" ? `\n  output   = "../generated/prisma"` : "";
  return (
    `generator client {\n  provider = "prisma-client-js"${output}\n}\n\n` +
    `datasource db {\n  provider = "sqlite"\n  url      = "file:${database}"\n}\n${MODELS}`
  );
}

/**
 * Generates a client into `dir`, laid out as `layout` says, for the SQLite file `database`, and makes its tables. The
 * project then requires it as `CLIENT_REQUEST[layout]` says.
 */
export async function generatePrisma(dir: string, layout: PrismaLayout, database: string): Promise<void> {
  const client = join(dir, "node_modules", "@prisma", "client");
  await mkdir(dirname(client), { recursive: true });
  if (layout === "default") {
    await mkdir(client);
    // The package's files, real, so that its `default.js` finds the `.prisma/client` beside this copy; its runtime,
    // linked, so that the module cache holds the workspace's.
    for (const entry of await readdir(PRISMA_CLIENT_DIR)) {
      const from = join(PRISMA_CLIENT_DIR, entry);
      if (entry === "runtime") await symlink(from, join(client, entry), "dir");
      else await cp(from, join(client, entry), { recursive: true, dereference: true });
    }
  } else {
    await symlink(PRISMA_CLIENT_DIR, client, "dir");
  }
  await mkdir(join(dir, "prisma"), { recursive: true });
  const schema = join(dir, "prisma", "schema.prisma");
  await writeFile(schema, prismaSchema(layout, database));
  const env = { ...process.env, ...PRISMA_QUIET };
  await run(process.execPath, [PRISMA_CLI, "generate", "--schema", schema], { cwd: dir, env });
  await run(process.execPath, [PRISMA_CLI, "db", "push", "--skip-generate", "--schema", schema], { cwd: dir, env });
}
